 3: # http://serverfault.com/questions/638507/how-to-access-host-variable-of-a-different-host-with-ansible
 4: # We need some facts from the install node, specifically to find address of slurm controller.
 5: #- name: grab facts from install nodes
 6: #  hosts: production
 7: #  strategy: free
 8: #  tasks: [ ]
 9: 
10: - name: Compute Nodes
11:   hosts: ohpc_images_compute
12:   strategy: free
13:   #remote_user: root
14:   become: yes
15:   connection: chroot
16: 
17:   roles: 
18:   - { role: ansible-role-fgci-ssh-keys, tags: [ 'ssh' ] }
19:   - { role: watermark-release, tags: [ 'always' ]  } 
20:   - { role: ansible-role-fgci-repo, tags: [ 'fgci7', 'repos' ] }
21:   - { role: ansible-role-yum, tags: [ 'yum', 'repos', 'login' ] }
22:   - { role: ansible-role-ohpc-repo, tags: [ 'yum', 'repos', 'ohpc' ] }
23: #  - { role: ansible-role-ohpc-node, tags: [ 'ohpc' ] }
24:   - { role: network_interface, tags: [ 'network' ] }
25:   - { role: ansible-role-hosts-int, tags: [ 'hosts'] }
26:   - { role: ansible-role-chrony, tags: [ 'ntp', 'chrony' ] }
27:   - { role: ansible-role-autofs, tags: [ 'autofs' ] }
28: #  - { role: ansible-role-nis, tags: [ 'nis' ] }
29: #  - { role: ansible-role-adauth, tags: [ 'auth' ] }
30:   - { role: ansible-role-pam, tags: [ 'auth', 'pam' ] }
31: #  - { role: ansible-role-nsswitch, tags: [ 'nsswitch', 'auth' ] }
32: #  - { role: ansible-role-yum-cron-2, tags: [ 'yumcron' ] }
33:   - { role: ansible-role-rsyslog, tags: [ 'rsyslog' ] }
34:   - { role: ansible-role-aliases, tags: [ 'aliases', 'email' ] }
35:   - { role: ansible-role-postfix, tags: [ 'postfix', 'mail' ] }
36:   - { role: ansible-role-idmapd, tags: [ 'idmapd' ] }
37:   - { role: ansible-role-nfs_mount, tags: [ 'nfsmount' ] }
38:   - { role: ansible-role-sshd-host-keys, tags: [ 'sshd', 'ssh', 'host-keys' ] }
39:   - { role: ansible-role-nhc, tags: [ 'nhc', 'slurm' ] }
40:   - { role: ansible-role-nhc-scripts, tags: [ 'nhc', 'slurm', 'nhc-scripts' ] }
41:   - { role: ansible-role-slurm, tags: [ 'slurm' ] }
42:   - { role: ansible-role-cvmfs, tags: [ 'cvmfs' ] }
43:   - { role: ansible-role-rdma, tags: [ 'rdma', 'infiniband' ] }
44:   - { role: ansible-role-system-limits, tags: [ 'limits', 'limit' ] }
45:   - { role: ansible-role-fgci-bash, tags: [ 'bash'] }
46:   - { role: ansible-role-fgci-install, tags: [ 'fgci-install', 'pull'] }
47:   - { role: ansible-role-dell, tags: [ 'dell' ] }
48:   - { role: ansible-role-smartd, tags: [ 'smartd', 'smart' ] }
49:   - { role: ansible-role-sshd, tags: [ 'sshd', 'ssh' ] }
50: #  - { role: ansible-role-collectd, tags: [ 'collectd', 'monitoring' ] }
51:   - { role: ansible-role-serial-console, tags: [ 'serial', 'console' ] }
52:   - { role: ansible-role-lustre_client, tags: [ 'lustre' ], when: lustre_client_enabled }
53:   - { role: ansible-role-systemd-journal, tags: [ 'systemd', 'journal', 'journald' ] }
54:   - { role: ansible-role-lldpd, tags: [ 'lldpd', 'lldp' ] }
55:   - { role: ansible-role-singularity, tags: [ 'singularity' ] }
56:   - { role: ansible-role-cuda, tags: [ 'cuda', 'nvidia' ],     when: (gpu is defined) and (gpu==True) }
57:   - { role: ansible-role-sacct_gpu, tags: [ 'gpu', 'nvidia' ], when: (gpu is defined) and (gpu==True) }
58:   - { role: ansible-role-ood-client, tags: [ 'ood' ], when: (ood_client is defined) and (ood_client==True) }
